import {readFile,writeFile,mkdir,open,rename,rm,stat} from 'node:fs/promises';
import {resolve} from 'node:path';
import {createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
import {voiceClipKey} from '../src/data/voiceKey.js';
import {OFFLINE_VOICE_MANIFEST} from '../src/data/offlineVoiceManifest.js';
const root=resolve(import.meta.dirname,'..');
const evidence=resolve(root,'docs/game-delivery-20261019/batch1/approved-provider-qa');
const inventory=JSON.parse(await readFile(resolve(root,'docs/game-delivery-20261019/batch1/spelling-voice-inventory.json'),'utf8'));
const pending=inventory.items.filter(x=>!x.existing);
const hash=createHash('sha256').update(JSON.stringify(pending.map(({text,lang,key,path})=>({text,lang,key,path})))).digest('hex');
if(hash!=='7a1b447f58b615f1abb08ac41c5fe9cf1e6b3aabac68c04e31cd12d4501c5f98'||pending.length!==56||pending.reduce((n,x)=>n+x.text.length,0)!==184)throw Error('Approved inventory changed');
for(const x of pending)if(voiceClipKey(x.text,x.lang)!==x.key||!/^\/audio\/en\/[a-f0-9]{8}-matilda\.mp3$/.test(x.path))throw Error('Invalid inventory key/path');
if(!process.argv.includes('--execute-approved')){console.log(JSON.stringify({inventorySha256:hash,requests:56,characters:184,noRetries:true,dryRun:true}));process.exit(0)}
await mkdir(evidence,{recursive:true});await mkdir(resolve(root,'tmp'),{recursive:true});
const stateFile=resolve(evidence,'spelling-generation-status.json');
let job;try{job=JSON.parse(await readFile(stateFile,'utf8'))}catch(error){if(error.code!=='ENOENT')throw error;job={inventorySha256:hash,approvedRequests:56,attempts:[],startedAt:new Date().toISOString(),status:'preparing'}}
if(job.inventorySha256!==hash||job.attempts.length>56)throw Error('Invalid prior job state');
if(job.status==='failed')throw Error('A prior attempt failed; automatic retry is forbidden. Inspect preserved progress.');
const lockPath=resolve(root,'tmp/offline-voice-generator.lock');const lock=await open(lockPath,'wx');await lock.writeFile(JSON.stringify({pid:process.pid,job:'approved-spelling-20261019',inventorySha256:hash}));
const journalFile=resolve(root,'tmp/offline-voice-request-state.json');const windowMs=600000;let journal;try{journal=JSON.parse(await readFile(journalFile,'utf8'))}catch(e){if(e.code!=='ENOENT')throw e;journal={requests:[],blockedUntil:0}}
const persist=async()=>{await writeFile(stateFile,JSON.stringify(job,null,2)+'\n')};
const manifest=new Map(Object.entries(OFFLINE_VOICE_MANIFEST));
const saveManifest=async()=>{const file=resolve(root,'src/data/offlineVoiceManifest.js');await writeFile(file+'.tmp','// Generated by the approved offline voice packagers.\nexport const OFFLINE_VOICE_MANIFEST = '+JSON.stringify(Object.fromEntries([...manifest].sort(([a],[b])=>a.localeCompare(b))),null,2)+';\n');await rename(file+'.tmp',file)};
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
try{
 job.status='running';await persist();
 for(const item of pending){
  const prior=job.attempts.find(x=>x.key===item.key);if(prior){if(prior.status!=='saved')throw Error('Prior incomplete attempt will not be retried: '+item.key);continue}
  journal.requests=journal.requests.filter(x=>Date.now()-x.at<windowMs);
  while(journal.requests.length>=30||journal.blockedUntil>Date.now()){
   const until=Math.max(journal.blockedUntil||0,(journal.requests[0]?.at||0)+windowMs+1000);
   job.status='waiting-rate-window';job.resumeAfter=new Date(until).toISOString();await persist();console.log(JSON.stringify({status:job.status,saved:job.attempts.filter(x=>x.status==='saved').length,resumeAfter:job.resumeAfter}));await sleep(Math.max(1,Math.min(30000,until-Date.now())));journal.requests=journal.requests.filter(x=>Date.now()-x.at<windowMs)
  }
  job.status='running';delete job.resumeAfter;
  const output=resolve(root,'public'+item.path);try{await stat(output);throw Error('Unexpected unrecorded existing output '+item.key)}catch(e){if(e.code!=='ENOENT')throw e}
  const receipt={key:item.key,text:item.text,path:item.path,attempt:job.attempts.length+1,startedAt:new Date().toISOString(),status:'attempted'};job.attempts.push(receipt);await persist();
  journal.requests.push({at:Date.now(),job:'approved-spelling-20261019',key:item.key});await writeFile(journalFile,JSON.stringify(journal,null,2)+'\n');
  const response=await fetch('https://dinospace-eight.vercel.app/api/voice',{method:'POST',headers:{'Content-Type':'application/json',Origin:'https://dinospace-eight.vercel.app'},body:JSON.stringify({text:item.text,language:'en'}),signal:AbortSignal.timeout(90000)});
  receipt.httpStatus=response.status;receipt.provider=response.headers.get('x-amari-voice-provider');receipt.profile=response.headers.get('x-amari-voice-profile');
  if(!response.ok||receipt.provider!=='elevenlabs'||receipt.profile!=='matilda'||!response.headers.get('content-type')?.startsWith('audio/mpeg'))throw Error('Voice request failed validation: '+response.status+' key '+item.key);
  const bytes=Buffer.from(await response.arrayBuffer());if(bytes.length<1000)throw Error('Voice response too small: '+item.key);
  await writeFile(output+'.tmp.mp3',bytes);execFileSync('ffmpeg',['-v','error','-i',output+'.tmp.mp3','-f','null','-'],{stdio:'pipe',timeout:30000});await rename(output+'.tmp.mp3',output);
  receipt.bytes=bytes.length;receipt.sha256=createHash('sha256').update(bytes).digest('hex');receipt.status='saved';receipt.finishedAt=new Date().toISOString();manifest.set(item.key,item.path);await saveManifest();await persist();console.log(JSON.stringify({saved:job.attempts.filter(x=>x.status==='saved').length,total:56,key:item.key}));
 }
 job.status='complete';job.completedAt=new Date().toISOString();await persist();console.log(JSON.stringify({status:'complete',generated:job.attempts.length,requestCap:56}));
}catch(error){job.status='failed';job.error=error.message;job.stoppedAt=new Date().toISOString();await persist();console.error(error.message);process.exitCode=1}
finally{await lock.close();await rm(lockPath)}
